```cpp
std::wstring FmtSize(ULONGLONG n) {
  wchar_t b[64];
  if (n < 1024) { swprintf(b, 64, L"%llu байт", n); return b; }
  const wchar_t* u[] = {L"Кб", L"Мб", L"Гб", L"Тб", L"Пб"};
  double v = (double)n; int i = -1;
  while (v >= 1024.0 && i < 4) { v /= 1024.0; i++; }
  swprintf(b, 64, L"%.1f %s", v, u[i]);
  std::wstring s = b;
  std::replace(s.begin(), s.end(), L'.', L',');
  return s;
}
```
