static HIMAGELIST g_sysSmall = nullptr;
static int g_iconFolder = 0, g_iconFile = 0;
static std::map<std::wstring,int> g_extIcons;

void InitShellIcons() {
  SHFILEINFOW fi{};
  g_sysSmall = (HIMAGELIST)SHGetFileInfoW(L"C:\\", FILE_ATTRIBUTE_DIRECTORY, &fi, sizeof(fi),
       SHGFI_SYSICONINDEX | SHGFI_SMALLICON | SHGFI_USEFILEATTRIBUTES);
  g_iconFolder = fi.iIcon;
  SHFILEINFOW ff{};
  SHGetFileInfoW(L"x.txt", FILE_ATTRIBUTE_NORMAL, &ff, sizeof(ff), SHGFI_SYSICONINDEX|SHGFI_SMALLICON|SHGFI_USEFILEATTRIBUTES);
  g_iconFile = ff.iIcon;
}
int IconForEntry(const Entry& e) {
  if (e.isUp) return g_iconFolder;
  if (e.isDir) return g_iconFolder;
  auto ext = e.ext();
  auto it = g_extIcons.find(ext);
  if (it != g_extIcons.end()) return it->second;
  std::wstring probe = L"x" + ext;
  SHFILEINFOW fi{};
  int idx = g_iconFile;
  if (SHGetFileInfoW(probe.c_str(), FILE_ATTRIBUTE_NORMAL, &fi, sizeof(fi), SHGFI_SYSICONINDEX|SHGFI_SMALLICON|SHGFI_USEFILEATTRIBUTES))
    idx = fi.iIcon;
  g_extIcons[ext] = idx;
  return idx;
}
HIMAGELIST ShellSmallImageList(){ return g_sysSmall; }
