bool ShellOp(HWND owner, const std::vector<std::wstring>& sources, const std::wstring& target, bool move) {
    std::wstring from;
    for (auto& s : sources) { from += s; from.push_back(L'\0'); }
    from.push_back(L'\0');
    std::wstring to;
    if (!target.empty()) { to = target; to.push_back(L'\0'); to.push_back(L'\0'); }
    SHFILEOPSTRUCTW op{};
    op.hwnd = owner;
    op.wFunc = move ? FO_MOVE : FO_COPY;
    op.pFrom = from.c_str();
    op.pTo = target.empty() ? nullptr : to.c_str();
    op.fFlags = FOF_ALLOWUNDO | FOF_NOCONFIRMMKDIR | FOF_WANTUNICODE;
    return SHFileOperationW(&op) == 0 && !op.fAnyOperationsAborted;
}
```
